//! K11 NVMe driver contract and controller validation.
use crate::device::Device;
pub const NVME_CLASS:u8=0x01;pub const NVME_SUBCLASS:u8=0x08;pub const NVME_PROGIF:u8=0x02;pub const NVME_ADMIN_QUEUE_DEPTH:u16=64;
#[derive(Clone,Copy,Debug)]pub struct NvmeController{pub device_id:u64,pub mmio_base:u64,pub doorbell_stride:u32,pub queue_depth:u16,pub online:bool}
impl NvmeController{pub fn from_device(d:&Device)->Result<Self,&'static str>{if d.class_code!=NVME_CLASS||d.subclass!=NVME_SUBCLASS||d.programming_interface!=NVME_PROGIF{return Err("not an NVMe controller")}let mut mmio=0;for r in d.resources{if let crate::device::Resource::Mmio{base,..}=r{mmio=base;break}}if mmio==0{return Err("NVMe BAR missing")}Ok(Self{device_id:d.id.0,mmio_base:mmio,doorbell_stride:4,queue_depth:NVME_ADMIN_QUEUE_DEPTH,online:false})}pub fn enable(&mut self)->Result<(),&'static str>{if self.mmio_base&0x3fff!=0{return Err("NVMe BAR alignment invalid")}self.online=true;Ok(())}pub fn validate_lba(&self,lba:u64,count:u32,namespace_blocks:u64)->Result<(),&'static str>{if !self.online||count==0{return Err("NVMe controller offline or empty request")}let end=lba.checked_add(count as u64).ok_or("NVMe LBA overflow")?;if end>namespace_blocks{return Err("NVMe request outside namespace")}Ok(())}}
